INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (1, 2, 1, 'Güzgüsüz fotoaparat + 35 mm adapterli obyektiv', 'Toy, ad günü və kiçik reklam çəkilişləri üçün ideal dəst. İki batareya, 128 GB SD kart, çanta və təmizləmə dəsti daxildir. Təhvil zamanı qısa təlimat verirəm, ilk dəfə istifadə edənlər üçün də rahatdır.', 'Bakı', 'Nəsimi', 45, 300, 'LIKE_NEW', 1, 14, 'ACTIVE', 5, 2, CURRENT_TIMESTAMP - INTERVAL '6360' HOUR, CURRENT_TIMESTAMP - INTERVAL '6240' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (2, 10, 1, 'Sony Alpha 7R IV + Zeiss obyektiv', 'Peşəkar foto və 4K video üçün tam kadrlı kamera. Zeiss obyektivi portret və məhsul çəkilişində çox kəskin nəticə verir. Üç batareya, şarj cihazı və ştativ əlavə olunur.', 'Sumqayıt', '12-ci mkr', 55, 400, 'GOOD', 2, 10, 'ACTIVE', 4.5, 2, CURRENT_TIMESTAMP - INTERVAL '7440' HOUR, CURRENT_TIMESTAMP - INTERVAL '7320' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (3, 2, 1, 'DJI Mavic Air 2 dron — Fly More dəsti', 'Üç batareya, ehtiyat pərlər, ND filtrlər və daşıma çantası ilə. 4K/60fps çəkir, küləkli Abşeron havasında da stabil uçur. Uçuş qaydalarını izah edirəm; şəhər mərkəzində uçuş icazəsi sizin məsuliyyətinizdədir.', 'Bakı', 'Yasamal', 40, 350, 'GOOD', 1, 7, 'ACTIVE', 4.67, 3, CURRENT_TIMESTAMP - INTERVAL '6216' HOUR, CURRENT_TIMESTAMP - INTERVAL '6096' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (4, 2, 1, 'GoPro HERO 13 Black + aksesuarlar', 'Dəniz, dağ və velosiped səfərləri üçün. Su altı qutusu, dəbilqə və sinə bərkidicisi, selfi çubuğu və iki batareya verilir. Qəbələ və Şahdağ səfərlərində dəfələrlə sınaqdan keçib.', 'Bakı', 'Yasamal', 15, 120, 'LIKE_NEW', 1, 21, 'ACTIVE', 5, 3, CURRENT_TIMESTAMP - INTERVAL '3936' HOUR, CURRENT_TIMESTAMP - INTERVAL '3816' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (5, 2, 1, 'Studiya işıq dəsti: 2 softboks + dayaqlar', 'Məhsul çəkilişi, video müsahibə və ev studiyası üçün iki 50×70 sm softboks. Dayaqlar 2 metrə qədər qalxır, lampalar istilik vermir. Hamısı bir çantaya yığılır, maşının yük yerinə rahat sığır.', 'Bakı', 'Nəsimi', 20, 80, 'GOOD', 1, 14, 'ACTIVE', 4.8, 5, CURRENT_TIMESTAMP - INTERVAL '2448' HOUR, CURRENT_TIMESTAMP - INTERVAL '2328' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (6, 5, 2, 'Akkumulyatorlu drel-burğu dəsti', 'İki 18V batareya, sürətli şarj cihazı və 30 ədədlik burğu-bit dəsti. Mebel yığmaq, rəf vurmaq və kiçik təmir üçün kifayət edir. Qutusu ilə təhvil verirəm.', 'Gəncə', 'Kəpəz', 8, 50, 'GOOD', 1, 14, 'ACTIVE', 5, 3, CURRENT_TIMESTAMP - INTERVAL '2808' HOUR, CURRENT_TIMESTAMP - INTERVAL '2688' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (7, 5, 2, 'Makita perforator (3 J)', 'Beton və kərpicdə deşik açmaq, kafel sökmək üçün. SDS-plus burğular (6–12 mm) və bir kəsik verilir. Toz maskası və eynəyi də əlavə edirəm.', 'Gəncə', 'Nizami', 12, 80, 'GOOD', 1, 10, 'ACTIVE', 4.33, 3, CURRENT_TIMESTAMP - INTERVAL '576' HOUR, CURRENT_TIMESTAMP - INTERVAL '456' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (8, 5, 2, 'Yüksək təzyiqli yuyucu (150 bar)', 'Maşın, həyət, xalça və eyvan təmizliyi üçün. 8 metrlik şlanq, köpük başlığı və iki fırça ilə. Su kranına birbaşa qoşulur.', 'Gəncə', 'Kəpəz', 15, 100, 'LIKE_NEW', 1, 7, 'ACTIVE', 5, 2, CURRENT_TIMESTAMP - INTERVAL '6192' HOUR, CURRENT_TIMESTAMP - INTERVAL '6072' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (9, 5, 2, 'Yaşıl şüalı lazer nivelir + ştativ', 'Kafel, alçıpan və mətbəx mebeli quraşdırmaq üçün 360° yaşıl xətt. Qapalı məkanda 30 metrə qədər aydın görünür. Ştativ və qəbuledici daxildir.', 'Gəncə', 'Nizami', 10, 120, 'LIKE_NEW', 1, 14, 'ACTIVE', 4.33, 3, CURRENT_TIMESTAMP - INTERVAL '1800' HOUR, CURRENT_TIMESTAMP - INTERVAL '1680' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (10, 2, 3, '4 nəfərlik kemp çadırı', 'İki girişli, tentli, yağışa davamlı çadır. Quba və Qusar meşələrində dəfələrlə qurulub — 10 dəqiqəyə qurulur. Döşəmə brezenti və ehtiyat payalar verilir.', 'Bakı', 'Nərimanov', 12, 60, 'GOOD', 2, 14, 'ACTIVE', 4.75, 4, CURRENT_TIMESTAMP - INTERVAL '3984' HOUR, CURRENT_TIMESTAMP - INTERVAL '3864' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (11, 9, 3, 'Yataq çantası (−5 °C) + döşəkcik', 'Payız və yaz gecələri üçün isti yataq çantası və şişirdilən döşəkcik. Hər kirayədən sonra yuyulur. Kompres çantası ilə gəlir.', 'Bakı', 'Binəqədi', 5, 30, 'GOOD', 2, 21, 'ACTIVE', 4, 1, CURRENT_TIMESTAMP - INTERVAL '5184' HOUR, CURRENT_TIMESTAMP - INTERVAL '5064' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (12, 9, 3, 'Portativ qaz ocağı + 2 balon', 'Kemp, piknik və bağ evi üçün. Pyezo alışdırıcı, küləyə qarşı qoruyucu, iki tam balon verilir. Çay və qəlyanaltı üçün kifayət edir.', 'Bakı', 'Binəqədi', 4, 20, 'GOOD', 1, 14, 'ACTIVE', 5, 1, CURRENT_TIMESTAMP - INTERVAL '7032' HOUR, CURRENT_TIMESTAMP - INTERVAL '6912' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (13, 9, 3, 'Treking çantası 65 L + çubuqlar', 'Çoxgünlük yürüşlər üçün rahat kürək sistemi, yağış örtüyü və iki treking çubuğu. Xınalıq və Laza marşrutlarında istifadə olunub.', 'Bakı', 'Binəqədi', 6, 40, 'GOOD', 2, 21, 'ACTIVE', 5, 1, CURRENT_TIMESTAMP - INTERVAL '5064' HOUR, CURRENT_TIMESTAMP - INTERVAL '4944' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (14, 5, 4, 'Dağ velosipedi Cube (29")', 'Hidravlik əyləclər, 12 sürət, ön amortizator. Göygöl və Hacıkənd yolları üçün ideal. Dəbilqə və qıfıl pulsuz verilir.', 'Gəncə', 'Kəpəz', 18, 150, 'LIKE_NEW', 1, 10, 'ACTIVE', 5, 3, CURRENT_TIMESTAMP - INTERVAL '3456' HOUR, CURRENT_TIMESTAMP - INTERVAL '3336' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (15, 6, 4, 'Elektrik skuter (25 km/s)', 'Bir şarjla 30 km yol gedir, qatlanır və liftə sığır. Bulvarda və şəhərdaxili qısa yollar üçün çox rahatdır. Şarj cihazı və qıfıl daxildir.', 'Sumqayıt', 'Mərkəz', 15, 120, 'GOOD', 1, 7, 'ACTIVE', 5, 3, CURRENT_TIMESTAMP - INTERVAL '552' HOUR, CURRENT_TIMESTAMP - INTERVAL '432' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (16, 6, 4, 'Şəhər velosipedi — səbətli', 'Dənizkənarı bulvarda gəzinti üçün yüngül, rahat oturacaqlı velosiped. Ön səbət və işıqlar var. Hündürlüyü 160–185 sm olanlar üçün.', 'Sumqayıt', '9-cu mkr', 10, 60, 'GOOD', 1, 14, 'ACTIVE', 5, 3, CURRENT_TIMESTAMP - INTERVAL '7032' HOUR, CURRENT_TIMESTAMP - INTERVAL '6912' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (17, 5, 4, 'Uşaq velosipedi (5–8 yaş) + köməkçi təkərlər', 'Köməkçi təkərləri çıxarıla bilən, yüngül çərçivəli uşaq velosipedi. Dəbilqə və diz qoruyucuları əlavə olunur.', 'Gəncə', 'Nizami', 6, 40, 'GOOD', 1, 14, 'ACTIVE', 5, 2, CURRENT_TIMESTAMP - INTERVAL '5424' HOUR, CURRENT_TIMESTAMP - INTERVAL '5304' HOUR);
INSERT INTO listings (id, owner_id, category_id, title, description, city, district, daily_price, deposit, item_condition, min_days, max_days, status, rating_avg, review_count, created_at, updated_at) VALUES (18, 7, 5, 'PlayStation 5 + 2 pult + 6 oyun', 'FIFA, Mortal Kombat, Spider-Man və başqa oyunlar yüklüdür. HDMI kabel, iki DualSense pult və şarj stansiyası. Ad günü və dost məclisləri üçün ən çox kirayə götürülən dəstim.', 'Bakı', 'Xətai', 20, 250, 'LIKE_NEW', 1, 7, 'ACTIVE', 4.5, 2, CURRENT_TIMESTAMP - INTERVAL '6816' HOUR, CURRENT_TIMESTAMP - INTERVAL '6696' HOUR);
